"""Builds deliver/text_replacements.tex (abstract, conclusion, section text with literal numbers) and results/summary_numbers.json from the
compare_*.json files, so that no number is typed by hand.  Run after compare.py (all three models) and paired_weekly.py."""
import sys, os, json
sys.dont_write_bytecode = True
RES = "/home/claude/subtasks4/6/results"; OUT = "/home/claude/subtasks4/6/deliver"
E = json.load(open(f"{RES}/compare_exact.json")); A = json.load(open(f"{RES}/compare_approx.json")); S = json.load(open(f"{RES}/compare_sub.json"))
P = json.load(open(f"{RES}/paired_weekly.json"))


def r0(x): return f"{abs(x):.0f}"
def r1(x): return f"{abs(x):.1f}"
def lh(v, d=1):
    """signed percentage change v (negative = lower) -> '6.5\\% lower' / '0.4\\% higher'"""
    return f"{abs(v):.{d}f}\\% " + ("lower" if v < 0 else "higher")


def blk(m, key):
    sc = m["scenarios"][key]
    fm, fo = sc["fixed_v7_prop_delta_vs_pct_min"], sc["fixed_v7_prop_delta_vs_pct_opt"]
    return dict(
        dJ_min=-fm["dJ_pct"], dJ_opt=-fo["dJ_pct"], dCLs_min=fm["dcaploss_pct"], dCLs_opt=fo["dcaploss_pct"],
        dEv_min=-fm["dEviol_pct"], dEv_opt=-fo["dEviol_pct"],
        eq1=sc["equal_exceedance"]["cap_pct_opt"]["saving_interp"], eq2=sc["equal_exceedance"]["cap_prop"]["saving_interp"],
        cap1=sc["equal_exceedance"]["cap_pct_opt"]["cap"], cap2=sc["equal_exceedance"]["cap_prop"]["cap"],
        Cresel=sc["designs"]["prop"]["C"], Jfix=sc["fixed_v7_prop"]["J"], fixC=sc["fixed_v7_prop"]["C"], pen=sc["fixed_v7_prop_penalty_vs_reselected_kUSD"],
        Jmin=sc["designs"]["pct_min"]["J"], Jopt=sc["designs"]["pct_opt"]["J"], Copt=sc["designs"]["pct_opt"]["C"])


KEYS = ["v7", "TF", "TF_low", "TF_high", "TD", "TD_low", "TD_high", "F_only", "T", "TFS"]
N = {nm: {k: blk(m, k) for k in KEYS} for nm, m in (("exact", E), ("approx", A), ("sub", S))}
rng = {}
for nm in N:
    for q in ("dJ_min", "dJ_opt", "dEv_min"):
        v = [N[nm][k][q] for k in KEYS if k not in ("v7", "TFS")]
        rng[f"{nm}_{q}"] = (min(v), max(v))
    for q in ("eq1", "eq2"):
        v = [N[nm][k][q]["pct"] for k in KEYS if k not in ("v7", "TFS")]
        rng[f"{nm}_{q}_pct"] = (min(v), max(v))
json.dump(dict(numbers=N, ranges_over_hardware_cases_excluding_v7_and_Scott=rng, paired=P), open(f"{RES}/summary_numbers.json", "w"), indent=1)

x = N["exact"]["TF"]; xr = rng; pw = P["TF"]
Sc = E["scenarios"]["TF"]
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import costmodel as cm
it = cm.hardware("filter", "central", Sc["fixed_v7_prop"]["C"], True, 0.0)      # items at the certified design (11.27 MVA)


def rg(lo, hi):
    """'12--16' or '12' when both round to the same integer"""
    return r0(lo) if r0(lo) == r0(hi) else f"{r0(lo)}--{r0(hi)}"
eq_a = Sc["equal_exceedance"]["cap_pct_opt"]; eq_b = Sc["equal_exceedance"]["cap_prop"]
